import {visualAssets,drawCell} from './engine/visual-assets.js?v=11';
const TAU=Math.PI*2,COLORS=['#b5f7ff','#58ffb2','#c384ff','#ffd16c','#65f6ff','#d7a5ff'];
export function presenceProfile(rank){const r=Math.max(0,Math.min(100,Math.floor(rank||0))),stage=Math.min(5,Math.floor(r/20));return {rank:r,stage,color:COLORS[stage],radius:16+stage*5+r*.06,height:75+r*.5,particles:r?4+Math.floor(r/4):0,layers:r?1+stage:0,shards:stage>=3?stage+2:0};}
// Persistent world-space mantle, rendered in rear/front passes around the character.
export function drawPresence(g,rank,t,front=false,moving=false,economy=false){const p=presenceProfile(rank);if(!p.rank)return;const {stage,color,radius,height}=p;g.save();g.globalCompositeOperation='lighter';g.strokeStyle=color;g.fillStyle=color;
if(!front){const pulse=.9+Math.sin(t*1.8)*.1;if(visualAssets.presence){g.globalAlpha=(.20+stage*.045)*pulse;drawCell(g,visualAssets.presence,3,2,stage,-radius*1.6,-height,radius*3.2,height+10);}const glow=g.createRadialGradient(0,-height*.4,2,0,-height*.4,radius*1.7);glow.addColorStop(0,color+'20');glow.addColorStop(1,color+'00');g.fillStyle=glow;g.fillRect(-radius*1.7,-height,radius*3.4,height+10);g.fillStyle=color;
for(let n=0;n<Math.min(3,1+stage);n++){const q=(t*(.15+stage*.012)+n*.37)%1;g.globalAlpha=(.07+stage*.02)*(1-q);g.lineWidth=.7+stage*.25;g.beginPath();g.ellipse(0,3,radius*(.7+q*.7),radius*(.28+q*.28),0,0,TAU);g.stroke();}}
const count=economy?Math.ceil(p.particles/2):p.particles;for(let n=0;n<count;n++){const q=(t*(.11+n%3*.012)+n*.618)%1,a=n*2.399+t*.18,depth=Math.sin(a);if((depth>0)!==front)continue;const x=Math.cos(a)*radius*(.75+.2*Math.sin(q*6)),y=3-q*height;g.globalAlpha=Math.sin(q*Math.PI)*(.28+stage*.045);g.fillStyle=n%4===0?'#fff':color;g.beginPath();g.arc(x,y,.5+stage*.12,0,TAU);g.fill();}
const streams=economy?2:2+stage;for(let n=0;n<streams;n++){const a=t*.18+n*TAU/streams,depth=Math.sin(a);if((depth>0)!==front)continue;const x=Math.cos(a)*radius*.8,flow=Math.sin(t*1.4+n)*4;g.globalAlpha=.10+stage*.018;g.lineWidth=.65+stage*.12;g.beginPath();g.moveTo(x,2);g.bezierCurveTo(x+flow,-height*.3,x-flow*2,-height*.7,x*.5+flow,-height*.96);g.stroke();}
for(let n=0;n<p.shards;n++){const a=t*.22+n*TAU/p.shards,depth=Math.sin(a);if((depth>0)!==front)continue;const x=Math.cos(a)*(radius+5),y=-height*.48+Math.sin(a)*radius*.35,bob=Math.sin(t*2+n)*2;g.globalAlpha=.35+stage*.055;g.fillStyle=n%2?'#eeeaff':color;g.beginPath();g.moveTo(x,y-4+bob);g.lineTo(x+2,y+bob);g.lineTo(x,y+5+bob);g.lineTo(x-2,y+bob);g.fill();}
if(stage>=4&&!front&&!economy){for(let n=0;n<2;n++){const side=n?-1:1,phase=t*.9+n;g.globalAlpha=.15+.1*Math.sin(t*2+n);g.lineWidth=.8;g.beginPath();g.moveTo(side*radius*.6,-height*.9);for(let j=1;j<=5;j++)g.lineTo(side*radius*(.65+Math.sin(Math.floor(t*5)+j*2.1+n)*.18),-height*(.9-j*.14));g.stroke();}}
if(stage===5&&!front){g.globalAlpha=.35;g.lineWidth=.8;g.beginPath();g.ellipse(0,-height*.86,radius*.8,4,t*.05,0,TAU);g.stroke();}if(moving&&!front){g.globalAlpha=.12+stage*.025;for(let n=0;n<2+stage;n++){g.beginPath();g.moveTo(-radius*.6+n*4,-20-n*5);g.quadraticCurveTo(-radius-8,-20-n*6,-radius*1.6-Math.sin(t*2+n)*5,-10-n*5);g.lineWidth=.8;g.stroke();}}g.restore();}
